	got := next.(*model)
	if got.logScrollY != 6 {
		t.Fatalf("pgup should scroll by viewport height, got %d", got.logScrollY)
	}

	next, _ = got.Update(tea.KeyPressMsg(tea.Key{Code: tea.KeyPgDown}))
